// Writes src/styles/themes.css (the 10 opt-in presets, roadmap C.2) from src/hooks/theme-builder.ts,
// so the CSS, the ThemeSwitcher and the dashboard customizer share one source. Run: npm run build:themes
import { writeFileSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { buildTheme, buildThemeCss, presetNames } from "../src/hooks/theme-builder.ts";

const HEADER = `/*
 * ChangelUI theme presets (opt-in). Generated by scripts/build-themes.ts from src/hooks/theme-builder.ts;
 * edit the presets there and run \`npm run build:themes\`.
 *
 * Import after theme.css, then pick a preset on any element (usually <html>):
 *   @import "changelui/themes.css";      (Tailwind apps)
 *   import "changelui/themes.css";       (bundlers, with styles.css)
 *   <html data-pui-theme="sunset" class="dark">
 *
 * Presets are orthogonal to light/dark: every preset has light and dark values, works at the root and
 * on nested islands, and a nested data-pui-theme always wins over its ancestors.
 */
`;

/** Pure: the full themes.css text. */
export function renderThemesCss(): string {
  return HEADER + "\n" + presetNames.map((name) => buildThemeCss({ preset: name })).join("\n");
}

function main(): void {
  const root = resolve(dirname(fileURLToPath(import.meta.url)), "..");
  const file = resolve(root, "src/styles/themes.css");
  writeFileSync(file, renderThemesCss());
  let warnings = 0;
  for (const name of presetNames) {
    for (const w of buildTheme({ preset: name }).warnings) {
      warnings++;
      console.warn(`build-themes: ${name} ${w.mode} --pui-${w.token} on --pui-${w.against} is ${w.ratio}:1 (needs ${w.required}:1)`);
    }
  }
  console.log(`build-themes: wrote ${presetNames.length} presets to src/styles/themes.css (${warnings} contrast warnings)`);
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) main();
